def build():
    ok = True
    for u in range(1, 9):
        code = f'B1-U0{u}'; pack = json.load(open(os.path.join(PACKS, f'iqra-pack-{code}.json'), encoding='utf-8')); out = {}
        for l in pack['lessons']:
            if l['code'] not in U: continue
            o = U[l['code']]; g, ca, ce = l['goal_ar'], l['can_do_ar'], l['can_do_en']
            for a, b in GOAL_SUBS: g, ca, ce = g.replace(a, b), ca.replace(a, b), ce.replace(a, b)
            for s in (g, ca, ce):
                if re.search(r'دقيقتين|100–120|two minutes|two-minute', s): print('  !! goal still old:', l['code'], s[:80]); ok = False
            kind = l['content']['produce']['kind']; m = o['model']; n = wc(m)
            lo, hi = (120, 160) if kind == 'write' else (225, 320)
            flag = '' if lo <= n <= hi else '  !! out of range'
            if flag: ok = False
            print(f"{l['code']} {kind:5} model {n:3} w · {len(m)} ch · check {len(o['check'])}{flag}")
            assert len(o['check']) <= 8 and all(len(c) <= 200 for c in o['check']) and len(m) <= 4000 and len(o['prompt']) <= 900
            out[l['code']] = {'goal_ar': g, 'can_do_ar': ca, 'can_do_en': ce, 'produce': {'kind': kind, 'prompt_ar': o['prompt'], 'checklist': o['check'], 'model_ar': m}}
        json.dump(out, open(os.path.join(HERE, f'{code}.json'), 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
    print('ALL OK' if ok else 'CHECK FLAGS')

if __name__ == '__main__': build()
